//  PRAT × SHADOW MONARCH AVATAR
//  Open jacket, V-taper goal physique, shadow wings,
//  dual energy daggers, slow purple lightning, blue eyes,
//  messy hair, earrings, chain, stubble
// ═══════════════════════════════════════════════════════════
const AVATAR_IMG = "data:image/jpeg;base64,";

const HunterAvatar = ({size=220}) => {
  const cRef=useRef(null),ps=useRef([]),fr=useRef(0);
  useEffect(()=>{
    const c=cRef.current;if(!c)return;const ctx=c.getContext("2d");
    c.width=size*2;c.height=size*2;ctx.scale(2,2);
    const sp=()=>({x:size/2+(Math.random()-0.5)*90,y:size*0.9,vx:(Math.random()-0.5)*0.7,vy:-(Math.random()*1.5+0.4),life:1,decay:Math.random()*0.007+0.003,sz:Math.random()*3+0.5,col:Math.random()>0.4?[147,51,234]:[59,130,246]});
    for(let i=0;i<50;i++){const p=sp();p.life=Math.random();ps.current.push(p)}
    const draw=()=>{ctx.clearRect(0,0,size,size);
      const g=ctx.createRadialGradient(size/2,size*0.4,5,size/2,size*0.4,size*0.5);
      g.addColorStop(0,"rgba(147,51,234,0.05)");g.addColorStop(1,"transparent");
      ctx.fillStyle=g;ctx.fillRect(0,0,size,size);
      ps.current.forEach(p=>{p.x+=p.vx;p.y+=p.vy;p.life-=p.decay;if(p.life<=0)Object.assign(p,sp());
        ctx.globalAlpha=p.life*0.5;ctx.fillStyle=`rgba(${p.col},${p.life})`;ctx.beginPath();ctx.arc(p.x,p.y,p.sz*p.life,0,Math.PI*2);ctx.fill();
        ctx.globalAlpha=p.life*0.1;ctx.beginPath();ctx.arc(p.x,p.y,p.sz*p.life*5,0,Math.PI*2);ctx.fill()});
      ctx.globalAlpha=1;fr.current=requestAnimationFrame(draw)};
    draw();return()=>cancelAnimationFrame(fr.current)},[size]);

  return(
    <div style={{position:"relative",width:size,height:size*1.5,margin:"0 auto",overflow:"hidden"}}>
      {/* Particle canvas behind */}
      <canvas ref={cRef} style={{position:"absolute",inset:0,width:size,height:size*1.5,zIndex:1}}/>
      {/* Actual image */}
      <div style={{position:"relative",zIndex:2,width:"100%",height:"100%",display:"flex",justifyContent:"center",animation:"auraBreath 5s ease-in-out infinite"}}>
        <img src={AVATAR_IMG} alt="" style={{height:"100%",objectFit:"contain",borderRadius:8,filter:"drop-shadow(0 0 30px rgba(147,51,234,0.5)) drop-shadow(0 0 60px rgba(59,130,246,0.25))"}}/>
      </div>
      {/* Lightning overlay SVG */}
      <svg viewBox="0 0 220 330" style={{position:"absolute",inset:0,width:"100%",height:"100%",zIndex:3,pointerEvents:"none"}}>
        <defs>
          <filter id="g2"><feGaussianBlur stdDeviation="4" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge></filter>
          <filter id="g3"><feGaussianBlur stdDeviation="8" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge></filter>
        </defs>
        {/* Slow purple lightning - left */}
        <g style={{animation:"slowBolt1 5.5s infinite"}}>
          <polyline points="30,15 48,55 38,62 56,100 46,108 58,140" fill="none" stroke="#9333ea" strokeWidth="2.5" filter="url(#g2)" strokeLinejoin="round"/>
          <polyline points="30,15 48,55 38,62 56,100 46,108 58,140" fill="none" stroke="#e9d5ff" strokeWidth="0.7" strokeLinejoin="round"/>
        </g>
        {/* Slow purple lightning - right */}
        <g style={{animation:"slowBolt2 6s infinite"}}>
          <polyline points="190,10 172,50 182,56 164,95 174,102 162,135" fill="none" stroke="#9333ea" strokeWidth="2.5" filter="url(#g2)" strokeLinejoin="round"/>
          <polyline points="190,10 172,50 182,56 164,95" fill="none" stroke="#e9d5ff" strokeWidth="0.7" strokeLinejoin="round"/>
        </g>
        {/* Lower left bolt */}
        <g style={{animation:"slowBolt3 5s infinite"}}>
          <polyline points="25,200 15,218 24,222 10,250" fill="none" stroke="#7c3aed" strokeWidth="1.8" filter="url(#g2)"/>
        </g>
        {/* Lower right bolt */}
        <g style={{animation:"slowBolt4 5.5s infinite"}}>
          <polyline points="195,195 205,215 196,218 210,245" fill="none" stroke="#7c3aed" strokeWidth="1.8" filter="url(#g2)"/>
        </g>
        {/* Center crackling */}
        <g style={{animation:"slowBolt1 4s infinite"}}>
          <polyline points="95,130 88,145 96,148 88,165" fill="none" stroke="#c084fc" strokeWidth="1" filter="url(#g2)"/>
        </g>
        <g style={{animation:"slowBolt3 4.5s infinite"}}>
          <polyline points="125,125 132,142 124,145 132,162" fill="none" stroke="#c084fc" strokeWidth="1" filter="url(#g2)"/>
        </g>
        {/* Top sparkle bolts */}
        <g style={{animation:"slowBolt2 7s infinite"}}>
          <polyline points="55,5 42,25 52,28 38,50" fill="none" stroke="rgba(147,51,234,0.6)" strokeWidth="1" filter="url(#g2)"/>
        </g>
        <g style={{animation:"slowBolt4 6.5s infinite"}}>
          <polyline points="165,8 178,28 168,32 182,52" fill="none" stroke="rgba(147,51,234,0.6)" strokeWidth="1" filter="url(#g2)"/>
        </g>
      </svg>
      {/* ARISE text */}
      <div style={{position:"absolute",bottom:4,left:0,right:0,textAlign:"center",zIndex:4,fontFamily:"'Orbitron',monospace",fontSize:10,fontWeight:900,letterSpacing:6,color:"#9333ea",textShadow:"0 0 22px rgba(147,51,234,0.9)",animation:"textGlitch 5s infinite"}}>A R I S E</div>
    </div>
  );
};

