const P=({title,children,style={},glow=false,accent="#9333ea"})=>(<div style={{background:"linear-gradient(135deg,rgba(8,10,22,0.97),rgba(10,14,30,0.99))",border:`1px solid ${glow?accent:"rgba(147,51,234,0.1)"}`,borderRadius:10,padding:14,position:"relative",overflow:"hidden",animation:glow?"pulseGlow 4s infinite":"fadeUp 0.5s ease-out",...style}}><div style={{position:"absolute",top:0,left:0,width:12,height:12,borderTop:`2px solid ${accent}`,borderLeft:`2px solid ${accent}`,borderRadius:"10px 0 0 0"}}/><div style={{position:"absolute",top:0,right:0,width:12,height:12,borderTop:`2px solid ${accent}`,borderRight:`2px solid ${accent}`,borderRadius:"0 10px 0 0"}}/><div style={{position:"absolute",bottom:0,left:0,width:12,height:12,borderBottom:`2px solid ${accent}`,borderLeft:`2px solid ${accent}`,borderRadius:"0 0 0 10px"}}/><div style={{position:"absolute",bottom:0,right:0,width:12,height:12,borderBottom:`2px solid ${accent}`,borderRight:`2px solid ${accent}`,borderRadius:"0 0 10px 0"}}/>{title&&<div style={{fontFamily:"'Orbitron',monospace",fontSize:9,fontWeight:700,color:accent,letterSpacing:3,textTransform:"uppercase",marginBottom:9,display:"flex",alignItems:"center",gap:5}}><span style={{width:5,height:5,background:accent,clipPath:"polygon(50% 0%,100% 50%,50% 100%,0% 50%)",display:"inline-block"}}/>{title}<div style={{flex:1,height:1,background:`linear-gradient(90deg,${accent}33,transparent)`}}/></div>}{children}</div>);
const Bar=({value,max,color="#9333ea",h=7,label=""})=>{const p=pc(value,max);return(<div>{label&&<div style={{display:"flex",justifyContent:"space-between",marginBottom:2,fontFamily:"'Share Tech Mono',monospace",fontSize:9,color:"#94a3b8"}}><span>{label}</span><span>{p}%</span></div>}<div style={{width:"100%",height:h,background:"rgba(15,23,42,0.9)",borderRadius:h/2,overflow:"hidden",border:"1px solid rgba(147,51,234,0.06)"}}><div style={{width:`${p}%`,height:"100%",background:`linear-gradient(90deg,${color}88,${color})`,borderRadius:h/2,transition:"width 0.6s",boxShadow:`0 0 6px ${color}44`}}/></div></div>)};
const St=({label,value,unit="",color="#9333ea",icon="◆"})=>(<div style={{background:"rgba(15,23,42,0.4)",border:"1px solid rgba(147,51,234,0.06)",borderRadius:6,padding:"8px 5px",textAlign:"center"}}><div style={{fontFamily:"'Share Tech Mono',monospace",fontSize:8,color:"#64748b",letterSpacing:1,marginBottom:2}}><span style={{color}}>{icon}</span> {label}</div><div style={{fontFamily:"'Orbitron',monospace",fontSize:16,fontWeight:700,color,textShadow:`0 0 10px ${color}44`,lineHeight:1.2}}>{value}</div>{unit&&<div style={{fontFamily:"'Rajdhani',sans-serif",fontSize:9,color:"#475569"}}>{unit}</div>}</div>);
const Bt=({children,onClick,color="#9333ea",small=false,ghost=false,full=false,active=false})=>(<button onClick={onClick} style={{fontFamily:"'Orbitron',monospace",fontSize:small?8:10,fontWeight:600,letterSpacing:1,padding:small?"4px 8px":"7px 14px",background:active?`${color}30`:ghost?"transparent":`${color}15`,color,border:`1px solid ${color}${active?"66":"33"}`,borderRadius:4,cursor:"pointer",textTransform:"uppercase",width:full?"100%":"auto",transition:"all 0.15s"}}>{children}</button>);
const Inp=({value,onChange,placeholder,type="text"})=>(<input type={type} value={value} onChange={onChange} placeholder={placeholder} style={{fontFamily:"'Share Tech Mono',monospace",fontSize:12,padding:"6px 9px",background:"rgba(15,23,42,0.9)",color:"#e2e8f0",border:"1px solid rgba(147,51,234,0.1)",borderRadius:4,outline:"none",width:"100%"}}/>);
const Ring=({label,cur,goal,color,unit="g"})=>{const p=pc(cur,goal),r=26,c=2*Math.PI*r;return(<div style={{textAlign:"center"}}><svg width={60} height={60} viewBox="0 0 60 60"><circle cx={30} cy={30} r={r} fill="none" stroke="rgba(30,41,59,0.6)" strokeWidth={4}/><circle cx={30} cy={30} r={r} fill="none" stroke={color} strokeWidth={4} strokeDasharray={`${c*p/100} ${c}`} strokeLinecap="round" transform="rotate(-90 30 30)" style={{transition:"stroke-dasharray 0.6s"}}/><text x={30} y={28} textAnchor="middle" fill={color} fontFamily="'Orbitron',monospace" fontSize={9} fontWeight={700}>{cur}</text><text x={30} y={39} textAnchor="middle" fill="#64748b" fontFamily="'Share Tech Mono',monospace" fontSize={7}>/{goal}{unit}</text></svg><div style={{fontFamily:"'Rajdhani',sans-serif",fontSize:9,color:"#94a3b8",fontWeight:600}}>{label}</div></div>)};
const Opt=({label,emoji,selected,onClick,color="#9333ea"})=>(<button onClick={onClick} style={{display:"flex",alignItems:"center",gap:6,padding:"7px 10px",width:"100%",textAlign:"left",background:selected?`${color}18`:"rgba(15,23,42,0.3)",border:`1px solid ${selected?color+"55":"rgba(147,51,234,0.05)"}`,borderRadius:5,cursor:"pointer"}}><span style={{fontSize:15}}>{emoji}</span><span style={{fontFamily:"'Rajdhani',sans-serif",fontSize:11,color:selected?color:"#94a3b8",fontWeight:selected?700:500}}>{label}</span>{selected&&<span style={{marginLeft:"auto",fontFamily:"'Orbitron',monospace",fontSize:7,color}}>✦</span>}</button>);
const Timer=({startTime,label,color="#9333ea"})=>{const[e,setE]=useState(0);useEffect(()=>{if(!startTime)return;const iv=setInterval(()=>setE(Math.floor((Date.now()-new Date(startTime).getTime())/1000)),1000);return()=>clearInterval(iv)},[startTime]);if(!startTime)return null;return(<div style={{textAlign:"center",padding:"8px 0"}}><div style={{fontFamily:"'Share Tech Mono',monospace",fontSize:8,color:"#64748b",letterSpacing:2,marginBottom:2}}>{label}</div><div style={{fontFamily:"'Orbitron',monospace",fontSize:22,fontWeight:700,color,animation:"timerPulse 2s infinite",textShadow:`0 0 12px ${color}55`}}>{dur(e)}</div></div>)};

// ═══════════════════════════════════════════════════════════
//  MAIN APP
// ═══════════════════════════════════════════════════════════
export default function App(){
  const[pro,sPro]=useState(DEF);const[wo,sWo]=useState({});const[nu,sNu]=useState({});const[bl,sBl]=useState([]);const[st,sSt]=useState({});const[dq,sDq]=useState({});const[life,sLife]=useState({});const[mis,sMis]=useState({});const[ref,sRef]=useState({});const[tim,sTim]=useState({});const[wk,sWk]=useState({});const[loading,sL]=useState(true);const[tab,sTab]=useState("home");const[flash,sFlash]=useState(null);const[day,sDay]=useState(td());const[modal,sMod]=useState(null);const[mKey,sMK]=useState(null);const[editEx,sEE]=useState([]);const[eatMode,sEM]=useState(null);const[selFood,sSF]=useState(null);const[custM,sCM]=useState({name:"",cals:"",protein:""});

  useEffect(()=>{(async()=>{const[p,w,n,b,s,q,l,m,r,t,wk_]=await Promise.all([ld(KS.p,DEF),ld(KS.w,{}),ld(KS.n,{}),ld(KS.bo,[]),ld(KS.st,{}),ld(KS.qu,{}),ld(KS.life,{}),ld(KS.mis,{}),ld(KS.ref,{}),ld(KS.tim,{}),ld(KS.wk,{})]);sPro(p);sWo(w);sNu(n);sBl(b);sSt(s);sDq(q);sLife(l);sMis(m);sRef(r);sTim(t);sWk(wk_);sL(false)})()},[]);

  const _p=async d=>{sPro(d);await sv(KS.p,d)};const _w=async d=>{sWo(d);await sv(KS.w,d)};const _n=async d=>{sNu(d);await sv(KS.n,d)};const _b=async d=>{sBl(d);await sv(KS.bo,d)};const _s=async d=>{sSt(d);await sv(KS.st,d)};const _q=async d=>{sDq(d);await sv(KS.qu,d)};const _l=async d=>{sLife(d);await sv(KS.life,d)};const _m=async d=>{sMis(d);await sv(KS.mis,d)};const _r=async d=>{sRef(d);await sv(KS.ref,d)};const _t=async d=>{sTim(d);await sv(KS.tim,d)};const _wk=async d=>{sWk(d);await sv(KS.wk,d)};
  const fl=m=>{sFlash(m);setTimeout(()=>sFlash(null),2800)};
  const addXP=useCallback(async(a,sh=0)=>{let p={...pro};p.xp+=a;p.shadowArmy=(p.shadowArmy||0)+sh;while(p.xp>=p.xpToNext){p.xp-=p.xpToNext;p.level++;p.xpToNext=Math.floor(p.xpToNext*1.15);const nr=[...RANKS].reverse().find(r=>p.level>=r.l);if(nr&&nr.n!==p.rank){p.rank=nr.n;fl(`RANK UP → ${nr.n}`)}}await _p(p)},[pro]);

  const tQ=dq[day]||genQ(day);const tL=life[day]||{};const tT=tim[day]||{};const tM=mis[day]||[];const tR=ref[day]||{};const tWk=wk[day?.slice(0,7)]||{pullups:0,pushups:0,miles:0};
  const ms=nu[day]||[];const tC=ms.reduce((s,m)=>s+m.cals,0);const tP=ms.reduce((s,m)=>s+m.protein,0);const tF=ms.reduce((s,m)=>s+m.fat,0);const tCa=ms.reduce((s,m)=>s+m.carbs,0);
  const rank=[...RANKS].reverse().find(r=>pro.level>=r.l)||RANKS[0];const lost=pro.startWeight-pro.currentWeight;
  useEffect(()=>{if(!dq[day])sDq(p=>({...p,[day]:genQ(day)}))},[day]);
  const[quote]=useState(()=>QUOTES[Math.floor(Math.random()*QUOTES.length)]);

  const compQ=async i=>{const q=[...(dq[day]||tQ)];if(q[i].done)return;q[i]={...q[i],done:true};await _q({...dq,[day]:q});await addXP(q[i].xp,1);fl(`QUEST CLEAR: ${q[i].n}`)};
  const logFood=async f=>{if(f.id==="custom"){if(!custM.name||!custM.cals)return;await _n({...nu,[day]:[...ms,{name:custM.name,cals:+custM.cals,protein:+(custM.protein||0),fat:0,carbs:0,time:hm()}]});sCM({name:"",cals:"",protein:""})}else{await _n({...nu,[day]:[...ms,{name:f.l,cals:f.cal,protein:f.p,fat:f.f,carbs:f.c,time:hm()}]})}await addXP(10);sSF(null);sEM(null);fl("Meal logged +10 XP")};
  const startFast=async()=>{await _t({...tim,[day]:{...tT,fastStart:nw()}});sEM("fasting");fl("Fasting started")};
  const endFast=async()=>{const d=Math.floor((Date.now()-new Date(tT.fastStart).getTime())/1000);await _t({...tim,[day]:{...tT,fastEnd:nw(),fastDur:d}});await addXP(25,1);sEM("eating");fl(`Fast done! ${dur(d)} +25 XP`)};
  const logShower=async a=>{if(a==="start"){await _t({...tim,[day]:{...tT,shwStart:nw()}});fl("Shower started")}else{const d=Math.floor((Date.now()-new Date(tT.shwStart).getTime())/1000);await _t({...tim,[day]:{...tT,shwEnd:nw(),shwDur:d}});await addXP(5);fl(`Shower: ${dur(d)}`)}};
  const logSleep=async a=>{if(a==="start"){await _t({...tim,[day]:{...tT,slpStart:nw()}});fl("Sleep started. Rest, Hunter.")}else{const d=Math.floor((Date.now()-new Date(tT.slpStart).getTime())/1000);await _t({...tim,[day]:{...tT,slpEnd:nw(),slpDur:d}});await addXP(15);fl(`Slept: ${dur(d)}`)}};
  const saveRef=async(k,v)=>{await _r({...ref,[day]:{...tR,[k]:v}});if(k==="sugar"&&v==="No")addXP(20,1);if(k==="vape"&&v==="No")addXP(30,1);if(k==="greed"&&v==="No")addXP(15);if(k==="profit"&&v==="Yes")addXP(25,1);if(k==="booty"&&v==="Yes")addXP(10)};
  const saveLife=async(k,v)=>{await _l({...life,[day]:{...tL,[k]:v}});if(k==="screen"&&+v<4)addXP(20);if(k==="people"&&+v>=3)addXP(15)};
  const selMission=async m=>{await _m({...mis,[day]:[...tM,{...m,done:false}]});fl(`Mission: ${m.n}`)};
  const compMission=async i=>{const u=[...tM];u[i]={...u[i],done:true};await _m({...mis,[day]:u});await addXP(u[i].xp,u[i].sh);fl(`COMPLETE: ${u[i].n}`)};
  const openWO=k=>{sMK(k);sEE(wo[day]?.template===k?wo[day].exercises:WO[k].ex.map(e=>({...e,completedSets:0,actualWeight:0})));sMod("wo")};
  const saveWO=async()=>{const t=WO[mKey];await _w({...wo,[day]:{template:mKey,name:t.name,exercises:editEx,date:day}});if(!wo[day]){await _p({...pro,totalWorkouts:(pro.totalWorkouts||0)+1});await addXP(50,1)}sMod(null);fl("WORKOUT DONE +50 XP")};

  const TABS=[{id:"home",l:"HOME",i:"◈"},{id:"checkin",l:"CHECK",i:"📋"},{id:"quest",l:"QUEST",i:"⚡"},{id:"mission",l:"MISSIONS",i:"🎯"},{id:"train",l:"TRAIN",i:"⚔"},{id:"fuel",l:"FUEL",i:"◉"},{id:"body",l:"BODY",i:"△"},{id:"eod",l:"EOD",i:"🌙"}];

  if(loading)return(<div style={{minHeight:"100vh",background:"#050810",display:"flex",alignItems:"center",justifyContent:"center"}}><style>{CSS}</style><div style={{textAlign:"center",animation:"auraBreath 3s infinite"}}><div style={{fontFamily:"'Orbitron',monospace",fontSize:16,fontWeight:700,color:"#9333ea",letterSpacing:4}}>SYSTEM LOADING</div></div></div>);

  return(
    <div style={{minHeight:"100vh",background:"linear-gradient(180deg,#050810,#080c1a,#050810)",color:"#e2e8f0",fontFamily:"'Rajdhani',sans-serif"}}>
      <style>{CSS}</style>
      <div style={{position:"fixed",inset:0,backgroundImage:"linear-gradient(rgba(147,51,234,0.012) 1px,transparent 1px),linear-gradient(90deg,rgba(147,51,234,0.012) 1px,transparent 1px)",backgroundSize:"40px 40px",pointerEvents:"none"}}/>
      {flash&&<div style={{position:"fixed",top:0,left:0,right:0,zIndex:1000,background:"linear-gradient(90deg,transparent,rgba(147,51,234,0.12),transparent)",padding:"11px 0",textAlign:"center",fontFamily:"'Orbitron',monospace",fontSize:12,fontWeight:700,color:"#9333ea",letterSpacing:3,textShadow:"0 0 20px rgba(147,51,234,0.8)",borderBottom:"1px solid rgba(147,51,234,0.3)",animation:"levelUp 0.4s"}}>◆ {flash} ◆</div>}

      {/* HEADER */}
      <div style={{padding:"12px 12px 6px",borderBottom:"1px solid rgba(147,51,234,0.06)"}}>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",maxWidth:520,margin:"0 auto"}}>
          <div><div style={{fontFamily:"'Orbitron',monospace",fontSize:8,color:rank.c,letterSpacing:3,fontWeight:700}}>{pro.rank}</div><div style={{fontFamily:"'Orbitron',monospace",fontSize:16,fontWeight:800,background:"linear-gradient(135deg,#9333ea,#3b82f6)",WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent"}}>{pro.name}</div></div>
          <div style={{display:"flex",alignItems:"center",gap:10}}>
            <div style={{textAlign:"center"}}><div style={{fontFamily:"'Share Tech Mono',monospace",fontSize:7,color:"#64748b"}}>SHADOWS</div><div style={{fontFamily:"'Orbitron',monospace",fontSize:13,fontWeight:800,color:"#7c3aed",animation:"shadowCount 3s infinite"}}>{pro.shadowArmy||0}</div></div>
            <div style={{textAlign:"right"}}><div style={{fontFamily:"'Share Tech Mono',monospace",fontSize:8,color:"#64748b"}}>LV</div><div style={{fontFamily:"'Orbitron',monospace",fontSize:24,fontWeight:900,color:"#9333ea",lineHeight:1,textShadow:"0 0 12px rgba(147,51,234,0.5)"}}>{pro.level}</div></div>
          </div>
        </div>
        <div style={{maxWidth:520,margin:"5px auto 0"}}><Bar value={pro.xp} max={pro.xpToNext} label={`XP: ${pro.xp}/${pro.xpToNext}`}/></div>
      </div>

      <div style={{display:"flex",gap:1,padding:"5px 2px",borderBottom:"1px solid rgba(147,51,234,0.05)",overflowX:"auto"}}>{TABS.map(t=>(<button key={t.id} onClick={()=>sTab(t.id)} style={{fontFamily:"'Orbitron',monospace",fontSize:7,fontWeight:600,letterSpacing:1,padding:"5px 6px",borderRadius:3,border:"none",cursor:"pointer",whiteSpace:"nowrap",background:tab===t.id?"rgba(147,51,234,0.1)":"transparent",color:tab===t.id?"#9333ea":"#475569",borderBottom:tab===t.id?"2px solid #9333ea":"2px solid transparent"}}>{t.i} {t.l}</button>))}</div>

      <div style={{display:"flex",justifyContent:"center",alignItems:"center",gap:8,padding:"7px 12px"}}><Bt small onClick={()=>{const d=new Date(day+"T12:00:00");d.setDate(d.getDate()-1);sDay(d.toISOString().slice(0,10))}}>◄</Bt><div style={{fontFamily:"'Share Tech Mono',monospace",fontSize:11,color:"#94a3b8",minWidth:110,textAlign:"center"}}>{day===td()?"⟐ TODAY":day} · {dn(day)}</div><Bt small onClick={()=>{const d=new Date(day+"T12:00:00");d.setDate(d.getDate()+1);sDay(d.toISOString().slice(0,10))}}>►</Bt></div>

      <div style={{maxWidth:520,margin:"0 auto",padding:"0 10px 90px"}}>

        {tab==="home"&&<div style={{display:"flex",flexDirection:"column",gap:10}}>
          <P glow><HunterAvatar size={220}/><div style={{textAlign:"center",marginTop:4}}><div style={{fontFamily:"'Orbitron',monospace",fontSize:11,fontWeight:700,color:"#9333ea",letterSpacing:3}}>SHADOW MONARCH PROTOCOL</div></div></P>
          <P accent="#7c3aed"><div style={{fontFamily:"'Rajdhani',sans-serif",fontSize:13,color:"#c084fc",fontStyle:"italic",lineHeight:1.5,textAlign:"center"}}>"{quote.t}"</div><div style={{fontFamily:"'Orbitron',monospace",fontSize:8,color:"#7c3aed",textAlign:"center",marginTop:4,letterSpacing:2}}>— {quote.b}</div></P>
          <P title="Stats"><div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:6}}><St label="Weight" value={pro.currentWeight} unit="lbs"/><St label="Lost" value={lost.toFixed(1)} color="#22d3ee" icon="▼"/><St label="Level" value={pro.level} color={rank.c} icon="★"/><St label="Army" value={pro.shadowArmy||0} color="#7c3aed" icon="👤"/></div></P>
          <P title="Weekly Goals"><div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:6}}><div><Bar value={tWk.pullups||0} max={50} color="#ef4444" label={`PU: ${tWk.pullups||0}/50`}/></div><div><Bar value={tWk.pushups||0} max={100} color="#f59e0b" label={`Push: ${tWk.pushups||0}/100`}/></div><div><Bar value={tWk.miles||0} max={6} color="#22d3ee" label={`Mi: ${tWk.miles||0}/6`}/></div></div></P>
          {tT.fastStart&&!tT.fastEnd&&<P title="Active Fast" glow accent="#f59e0b"><Timer startTime={tT.fastStart} label="FASTING" color="#f59e0b"/><Bt onClick={endFast} color="#22d3ee" full>Break Fast</Bt></P>}
        </div>}

        {tab==="checkin"&&<div style={{display:"flex",flexDirection:"column",gap:10}}>
          <P title="🍽 Eat or Fast?" glow accent="#f59e0b">{!eatMode&&!tT.fastStart&&<div style={{display:"flex",gap:6}}><Bt onClick={()=>sEM("eating")} color="#22d3ee" full>I Ate</Bt><Bt onClick={startFast} color="#f59e0b" full>Fasting</Bt></div>}{tT.fastStart&&!tT.fastEnd&&<div><Timer startTime={tT.fastStart} label="FASTING" color="#f59e0b"/><Bt onClick={endFast} color="#22d3ee" full>Break Fast +25 XP</Bt></div>}{tT.fastEnd&&<div style={{fontFamily:"'Share Tech Mono',monospace",fontSize:11,color:"#22d3ee",textAlign:"center",padding:6}}>✦ Fasted {dur(tT.fastDur)}</div>}{eatMode==="eating"&&<div style={{display:"flex",flexDirection:"column",gap:3,marginTop:5}}><div style={{fontFamily:"'Orbitron',monospace",fontSize:8,color:"#94a3b8",letterSpacing:2}}>WHAT DID YOU EAT?</div>{FOODS.map(f=>(<Opt key={f.id} label={`${f.l}${f.cal?` (${f.cal}cal)`:""}`} emoji={f.e} selected={selFood===f.id} onClick={()=>sSF(f.id)} color="#22d3ee"/>))}{selFood==="custom"&&<div style={{display:"flex",flexDirection:"column",gap:3,marginTop:3}}><Inp placeholder="What?" value={custM.name} onChange={e=>sCM({...custM,name:e.target.value})}/><div style={{display:"flex",gap:3}}><Inp type="number" placeholder="Cal" value={custM.cals} onChange={e=>sCM({...custM,cals:e.target.value})}/><Inp type="number" placeholder="Protein" value={custM.protein} onChange={e=>sCM({...custM,protein:e.target.value})}/></div></div>}{selFood&&<Bt onClick={()=>logFood(FOODS.find(f=>f.id===selFood))} color="#22d3ee" full>Log Meal +10 XP</Bt>}</div>}</P>
          <P title="🚿 Shower">{!tT.shwStart?<Bt onClick={()=>logShower("start")} color="#60a5fa" full>Start Timer</Bt>:!tT.shwEnd?<div><Timer startTime={tT.shwStart} label="SHOWER" color="#60a5fa"/><Bt onClick={()=>logShower("end")} color="#22d3ee" full>Done</Bt></div>:<div style={{fontFamily:"'Share Tech Mono',monospace",fontSize:11,color:"#60a5fa",textAlign:"center"}}>✦ {dur(tT.shwDur)}</div>}</P>
          <P title="😴 Sleep">{!tT.slpStart?<Bt onClick={()=>logSleep("start")} color="#a78bfa" full>Going to Sleep</Bt>:!tT.slpEnd?<div><Timer startTime={tT.slpStart} label="SLEEPING" color="#a78bfa"/><Bt onClick={()=>logSleep("end")} color="#22d3ee" full>Woke Up +15 XP</Bt></div>:<div style={{fontFamily:"'Share Tech Mono',monospace",fontSize:11,color:"#a78bfa",textAlign:"center"}}>✦ Slept {dur(tT.slpDur)}</div>}</P>
          <P title="📱 Screen Time"><Inp type="number" placeholder="Hours" value={tL.screen||""} onChange={e=>saveLife("screen",e.target.value)}/></P>
          <P title="💬 People Talked To"><Inp type="number" placeholder="Count" value={tL.people||""} onChange={e=>saveLife("people",e.target.value)}/></P>
          <P title="⚖️ Weight"><div style={{display:"flex",gap:4}}><Inp type="number" placeholder="lbs" value={tL.weight||""} onChange={e=>saveLife("weight",e.target.value)}/><Bt onClick={async()=>{if(!tL.weight)return;await _b([...bl.filter(b=>b.date!==day),{date:day,weight:+tL.weight}].sort((a,b)=>a.date.localeCompare(b.date)));await _p({...pro,currentWeight:+tL.weight});await addXP(15);fl("Logged +15 XP")}} color="#22d3ee">Log</Bt></div></P>
          <P title="💪 Weekly Fitness"><div style={{display:"flex",flexDirection:"column",gap:3}}>{[["Pull-ups","pullups"],["Push-ups","pushups"],["Miles","miles"]].map(([l,k])=>(<div key={k} style={{display:"flex",gap:3,alignItems:"center"}}><span style={{fontFamily:"'Rajdhani',sans-serif",fontSize:10,color:"#94a3b8",minWidth:60}}>{l}:</span><Inp type="number" placeholder="Today" onChange={e=>{const m=day.slice(0,7);const w={...tWk,[k]:(tWk[k]||0)+Number(e.target.value||0)};_wk({...wk,[m]:w})}}/></div>))}</div></P>
        </div>}

        {tab==="quest"&&<div style={{display:"flex",flexDirection:"column",gap:10}}>
          <P title="⚡ Daily Quests" glow accent="#ef4444"><div style={{fontFamily:"'Rajdhani',sans-serif",fontSize:10,color:"#f87171",padding:"4px 8px",background:"rgba(239,68,68,0.04)",borderRadius:4,border:"1px solid rgba(239,68,68,0.1)",animation:"questPulse 2s infinite",marginBottom:6}}>⚠ The System does not forgive weakness.</div>{tQ.map((q,i)=>(<div key={i} style={{padding:"9px",marginBottom:4,background:q.done?"rgba(34,211,238,0.04)":"rgba(15,23,42,0.3)",border:`1px solid ${q.done?"rgba(34,211,238,0.15)":"rgba(239,68,68,0.06)"}`,borderRadius:6}}><div style={{fontFamily:"'Rajdhani',sans-serif",fontSize:13,fontWeight:700,color:q.done?"#22d3ee":"#e2e8f0"}}>{q.done?"✦ ":""}{q.n}</div><div style={{fontFamily:"'Share Tech Mono',monospace",fontSize:8,color:"#475569"}}>Target: {fm(q.t)} {q.u} · +{q.xp} XP</div>{!q.done&&<Bt onClick={()=>compQ(i)} color="#22d3ee" full small>Complete</Bt>}</div>))}</P>
        </div>}

        {tab==="mission"&&<div style={{display:"flex",flexDirection:"column",gap:10}}>
          {tM.length>0&&<P title="Active" glow>{tM.map((m,i)=>(<div key={i} style={{padding:"7px",marginBottom:3,background:m.done?"rgba(34,211,238,0.04)":"rgba(15,23,42,0.3)",border:`1px solid ${m.done?"rgba(34,211,238,0.15)":"rgba(147,51,234,0.06)"}`,borderRadius:5}}><div style={{fontFamily:"'Rajdhani',sans-serif",fontSize:12,fontWeight:700,color:m.done?"#22d3ee":"#e2e8f0"}}>{m.c} {m.done?"✦ ":""}{m.n}</div><div style={{display:"flex",justifyContent:"space-between",marginTop:2}}><span style={{fontFamily:"'Share Tech Mono',monospace",fontSize:8,color:"#64748b"}}>+{m.xp}XP +{m.sh}sh</span>{!m.done&&<Bt small onClick={()=>compMission(i)} color="#22d3ee">Done</Bt>}</div></div>))}</P>}
          {Object.entries(MISSIONS).map(([cat,pool])=>(<P key={cat} title={cat.toUpperCase()} accent={cat==="money"?"#f59e0b":cat==="discipline"?"#ef4444":cat==="fitness"?"#22d3ee":"#9333ea"}>{pool.map((m,i)=>{const a=tM.some(x=>x.n===m.n);return(<button key={i} onClick={()=>!a&&selMission(m)} style={{display:"flex",justifyContent:"space-between",padding:"7px 9px",marginBottom:2,width:"100%",textAlign:"left",background:a?"rgba(147,51,234,0.05)":"rgba(15,23,42,0.2)",border:`1px solid ${a?"rgba(147,51,234,0.1)":"rgba(147,51,234,0.03)"}`,borderRadius:4,cursor:a?"default":"pointer"}}><span style={{fontFamily:"'Rajdhani',sans-serif",fontSize:11,color:a?"#64748b":"#e2e8f0"}}>{m.c} {m.n}</span><span style={{fontFamily:"'Orbitron',monospace",fontSize:7,color:a?"#64748b":"#f59e0b"}}>{a?"✦":"+"+m.xp}</span></button>)})}</P>))}
        </div>}

        {tab==="train"&&<div style={{display:"flex",flexDirection:"column",gap:10}}>
          <P title="Workouts" glow accent="#f59e0b">{Object.entries(WO).map(([k,t])=>{const d=wo[day]?.template===k;return(<button key={k} onClick={()=>openWO(k)} style={{display:"flex",justifyContent:"space-between",padding:"9px",marginBottom:3,width:"100%",textAlign:"left",background:d?"rgba(34,211,238,0.04)":"rgba(15,23,42,0.3)",border:`1px solid ${d?"rgba(34,211,238,0.12)":"rgba(147,51,234,0.04)"}`,borderRadius:5,cursor:"pointer"}}><div><div style={{fontFamily:"'Orbitron',monospace",fontSize:10,fontWeight:600,color:d?"#22d3ee":"#e2e8f0"}}>{t.emoji} {t.name}</div><div style={{fontFamily:"'Share Tech Mono',monospace",fontSize:8,color:"#64748b",marginTop:1}}>{k} · +50 XP</div></div><span style={{fontFamily:"'Orbitron',monospace",fontSize:8,color:d?"#22d3ee":"#f59e0b"}}>{d?"DONE":"START"}</span></button>)})}</P>
        </div>}

        {tab==="fuel"&&<div style={{display:"flex",flexDirection:"column",gap:10}}>
          <P title="Macros" glow accent="#a78bfa"><div style={{display:"flex",justifyContent:"space-around",flexWrap:"wrap",gap:3}}><Ring label="Cal" cur={tC} goal={pro.dailyCals} color="#f59e0b" unit=""/><Ring label="Pro" cur={tP} goal={pro.protein} color="#ef4444"/><Ring label="Fat" cur={tF} goal={pro.fat} color="#f59e0b"/><Ring label="Carb" cur={tCa} goal={pro.carbs} color="#3b82f6"/></div></P>
          {ms.length>0&&<P title="Log">{ms.map((m,i)=>(<div key={i} style={{display:"flex",justifyContent:"space-between",padding:"3px 0",borderBottom:"1px solid rgba(147,51,234,0.03)"}}><span style={{fontFamily:"'Rajdhani',sans-serif",fontSize:11,color:"#e2e8f0"}}>{m.name}</span><span style={{fontFamily:"'Share Tech Mono',monospace",fontSize:9,color:"#a78bfa"}}>{m.cals}cal P{m.protein}</span></div>))}</P>}
        </div>}

        {tab==="body"&&<div style={{display:"flex",flexDirection:"column",gap:10}}>
          <P title="Transform" glow accent="#22d3ee"><div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:6,marginBottom:8}}><St label="Start" value={pro.startWeight} color="#64748b" icon="◇"/><St label="Now" value={pro.currentWeight} icon="◆"/><St label="Goal" value={pro.targetWeight} color="#22d3ee" icon="★"/></div><Bar value={lost} max={pro.startWeight-pro.targetWeight} color="#22d3ee" label={`${lost.toFixed(1)}/${(pro.startWeight-pro.targetWeight).toFixed(1)} lbs`}/></P>
          {bl.length>0&&<P title="History">{[...bl].reverse().slice(0,10).map((b,i)=>(<div key={i} style={{display:"flex",justifyContent:"space-between",padding:"3px 0",borderBottom:"1px solid rgba(147,51,234,0.03)",fontFamily:"'Share Tech Mono',monospace",fontSize:9}}><span style={{color:"#64748b"}}>{b.date}</span><span style={{color:"#9333ea"}}>{b.weight}lbs</span></div>))}</P>}
        </div>}

        {tab==="eod"&&<div style={{display:"flex",flexDirection:"column",gap:10}}>
          <P title="🌙 End of Day" glow accent="#a78bfa">
            {[{k:"moodToday",l:"HOW DO I FEEL TODAY?",opts:["🔥 On Fire","😤 Locked In","😐 Neutral","😴 Drained","💀 Cooked"],c:"#a78bfa"},{k:"moodTmrw",l:"TOMORROW?",opts:["⚡ Ready","🎯 Focused","😬 Anxious","🤷 Uncertain"],c:"#7c3aed"},{k:"sugar",l:"SUGAR TODAY?",opts:["Yes","No (+20 XP)"],c:"#ef4444"},{k:"vape",l:"VAPE TODAY?",opts:["Yes","No (+30 XP)"],c:"#ef4444"},{k:"greed",l:"GREED IN MARKET?",opts:["Yes","No (+15 XP)"],c:"#f59e0b"},{k:"profit",l:"PROFIT TODAY?",opts:["Yes (+25 XP)","No"],c:"#22d3ee"},{k:"booty",l:"GF SEND 🍑?",opts:["Yes (+10 XP)","No"],c:"#ec4899"},{k:"improveToday",l:"IMPROVE TODAY?",opts:["More discipline","Better food","Train harder","Sleep earlier","Less screen","Be social","Study","Make money"],c:"#9333ea"},{k:"improveTmrw",l:"IMPROVE TOMORROW?",opts:["Wake earlier","Meal prep","No vaping","Gym first","No scrolling","Network","Trade better","Be kind to self"],c:"#7c3aed"}].map(q=>(<div key={q.k} style={{marginBottom:8}}><div style={{fontFamily:"'Orbitron',monospace",fontSize:8,color:"#94a3b8",letterSpacing:2,marginBottom:3}}>{q.l}</div><div style={{display:"flex",gap:3,flexWrap:"wrap"}}>{q.opts.map(o=>(<Bt key={o} small onClick={()=>saveRef(q.k,o.replace(/ \(.*\)/,""))} active={tR[q.k]===o.replace(/ \(.*\)/,"")} color={q.c}>{o}</Bt>))}</div></div>))}
          </P>
          <P title="🔮 10-Year Vision" accent="#7c3aed"><div style={{fontFamily:"'Rajdhani',sans-serif",fontSize:11,color:"#94a3b8",lineHeight:1.7}}>{["E-Rank → Shadow Monarch","175 lbs 8% BF — Jin Woo physique","Financial freedom","Shadow army built","Am I happy? Am I proud?"].map((t,i)=>(<div key={i} style={{padding:"3px 0"}}><span style={{color:"#7c3aed"}}>◆</span> {t}</div>))}</div></P>
          <P><div style={{fontFamily:"'Rajdhani',sans-serif",fontSize:13,color:"#c084fc",fontStyle:"italic",textAlign:"center"}}>"{QUOTES[Math.floor(Date.now()/86400000)%QUOTES.length].t}"</div><div style={{fontFamily:"'Orbitron',monospace",fontSize:7,color:"#7c3aed",textAlign:"center",marginTop:3,letterSpacing:2}}>— {QUOTES[Math.floor(Date.now()/86400000)%QUOTES.length].b}</div></P>
        </div>}
      </div>

      {modal==="wo"&&mKey&&<div style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.9)",zIndex:999,display:"flex",alignItems:"center",justifyContent:"center",padding:8}}><div style={{width:"100%",maxWidth:440,maxHeight:"85vh",overflow:"auto",background:"linear-gradient(135deg,#070a16,#0f172a)",border:"1px solid rgba(147,51,234,0.2)",borderRadius:10,padding:14}}><div style={{display:"flex",justifyContent:"space-between",marginBottom:10}}><span style={{fontFamily:"'Orbitron',monospace",fontSize:11,fontWeight:700,color:"#f59e0b",letterSpacing:2}}>⚔ {WO[mKey].name}</span><button onClick={()=>sMod(null)} style={{background:"none",border:"none",color:"#64748b",fontSize:16,cursor:"pointer"}}>✕</button></div>{editEx.map((e,i)=>(<div key={i} style={{padding:"6px 0",borderBottom:"1px solid rgba(147,51,234,0.04)"}}><div style={{fontFamily:"'Rajdhani',sans-serif",fontSize:11,color:"#e2e8f0",fontWeight:600,marginBottom:3}}>{e.name}</div><div style={{display:"flex",gap:4,alignItems:"center"}}><span style={{fontSize:7,color:"#64748b",fontFamily:"'Share Tech Mono',monospace"}}>SETS</span><input type="number" value={e.completedSets||e.sets} onChange={ev=>{const a=[...editEx];a[i]={...a[i],completedSets:+ev.target.value};sEE(a)}} style={{width:36,padding:"2px",background:"rgba(15,23,42,0.9)",color:"#e2e8f0",border:"1px solid rgba(147,51,234,0.1)",borderRadius:3,fontFamily:"'Share Tech Mono',monospace",fontSize:10,textAlign:"center"}}/><span style={{fontSize:9,color:"#475569",fontFamily:"'Share Tech Mono',monospace"}}>×{e.reps}</span><span style={{fontSize:7,color:"#64748b",fontFamily:"'Share Tech Mono',monospace"}}>LBS</span><input type="number" value={e.actualWeight||""} placeholder="0" onChange={ev=>{const a=[...editEx];a[i]={...a[i],actualWeight:+ev.target.value};sEE(a)}} style={{width:42,padding:"2px",background:"rgba(15,23,42,0.9)",color:"#e2e8f0",border:"1px solid rgba(147,51,234,0.1)",borderRadius:3,fontFamily:"'Share Tech Mono',monospace",fontSize:10,textAlign:"center"}}/></div></div>))}<div style={{marginTop:10,display:"flex",gap:5}}><Bt onClick={saveWO} color="#22d3ee">◆ Complete</Bt><Bt onClick={()=>sMod(null)} ghost color="#64748b">Cancel</Bt></div></div></div>}
    </div>
  );
}
